/**
 * A typed Management API client, as returned by `createManagementApiClient` or
 * the `client` property of `createAuthenticatedManagementAPI`.
 */
export type ApiClient = ManagementApiClient

/**
 * A project as returned by the Management API.
 */
export type Project =
  operations['getV1Projects']['responses'][200]['content']['application/json']['data'][number]

/**
 * A database as returned by the Management API.
 */
export type Database =
  operations['getV1ProjectsByProjectIdDatabases']['responses'][200]['content']['application/json']['data'][number]

/**
 * The result of creating a connection to a Prisma Postgres database.
 */
export type ConnectionResult = {
  connectionString: string
}

type ApiError = {
  code?: string
  message?: string
}

function extractApiError(error: unknown): ApiError {
  if (error && typeof error === 'object' && 'error' in error) {
    const inner = (error as { error?: unknown }).error
    if (inner && typeof inner === 'object') {
      const { code, message } = inner as { code?: unknown; message?: unknown }
      return {
        code: typeof code === 'string' ? code : undefined,
        message: typeof message === 'string' ? message : undefined,
      }
    }
  }
  return {}
}

function isAuthenticationError(code?: string): boolean {
  if (!code) return false
  const normalized = code.toLowerCase()
  return normalized.includes('auth') || normalized === 'forbidden'
}

function isNotFoundError(code?: string): boolean {
  if (!code) return false
  const normalized = code.toLowerCase()
  return /not[-_ ]?found/.test(normalized)
}

/**
 * Removes sensitive data (connection strings and API keys) from an error message so
 * that it can be safely displayed to the user or written to logs.
 */
export function sanitizeErrorMessage(message: string): string {
  return message
    .replace(/(?:prisma\+)?postgres:\/\/[^\s'"]+/gi, '[REDACTED_URL]')
    .replace(/--api-key[=\s]+\S+/gi, '--api-key [REDACTED]')
}

/**
 * Returns the list of projects the given client has access to.
 *
 * @throws if the Management API returns an error.
 */
export async function listProjects(client: ApiClient): Promise<Project[]> {
  const { data, error } = await client.GET('/v1/projects')

  if (error) {
    const { message } = extractApiError(error)
    throw new Error(message ?? 'Failed to list projects')
  }

  return data?.data ?? []
}

/**
 * Returns the list of databases for the given project.
 *
 * @throws if the Management API returns an error.
 */
export async function listDatabases(client: ApiClient, projectId: string): Promise<Database[]> {
  const { data, error } = await client.GET('/v1/projects/{projectId}/databases', {
    params: { path: { projectId } },
  })

  if (error) {
    const { message } = extractApiError(error)
    throw new Error(message ?? 'Failed to list databases')
  }

  return data?.data ?? []
}

/**
 * Creates a new connection string for the given database and returns the preferred
 * connection string, preferring the direct endpoint, then the pooled endpoint, then
 * the deprecated top-level `connectionString` field.
 *
 * @throws with `Invalid credentials` on authentication failures, a message matching
 * `not found` on not-found errors, `No connection string found` when the response
 * contains no usable connection string, and the original API error message otherwise.
 */
export async function createDevConnection(client: ApiClient, databaseId: string): Promise<ConnectionResult> {
  const { data, error } = await client.POST('/v1/databases/{databaseId}/connections', {
    params: { path: { databaseId } },
    body: { name: 'Prisma CLI' },
  })

  if (error) {
    const { code, message } = extractApiError(error)

    if (isAuthenticationError(code)) {
      throw new Error('Invalid credentials. Please check your API key and try again.')
    }
    if (isNotFoundError(code)) {
      throw new Error(`Database not found${message ? `: ${message}` : ''}`)
    }
    throw new Error(message ?? 'Failed to create connection')
  }

  const connection = data?.data
  const connectionString =
    connection?.endpoints?.direct?.connectionString ??
    connection?.endpoints?.pooled?.connectionString ??
    connection?.connectionString

  if (!connectionString) {
    throw new Error('No connection string found in the API response.')
  }

  return { connectionString }
}
