import path from 'node:path'

import type { ConnectionResult } from './management-api'

/**
 * The result of writing to a `.env` file.
 */
export type EnvFileResult = {
  created: boolean
  added: string[]
  updated: string[]
}

/**
 * The state of the `.gitignore` file with respect to the `.env` entry.
 */
export type GitignoreStatus = 'no-file' | 'ok' | 'missing-entry'

function escapeRegExp(input: string): string {
  return input.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function formatLine(key: string, value: string): string {
  return `${key}='${value}'`
}

/**
 * Creates or updates a `.env` file at the given path with the given key-value pairs.
 *
 * Values are always written with single quotes to prevent shell/dotenv variable
 * expansion. Existing keys are updated in-place, new keys are appended. Returns
 * metadata describing which keys were created, added, or updated.
 */
export function upsertEnvFile(envPath: string, vars: Record<string, string>): EnvFileResult {
  const entries = Object.entries(vars)

  if (!fs.existsSync(envPath)) {
    const content = entries.map(([key, value]) => `${formatLine(key, value)}\n`).join('')
    fs.writeFileSync(envPath, content)
    return { created: true, added: entries.map(([key]) => key), updated: [] }
  }

  let content = fs.readFileSync(envPath, 'utf8')
  const added: string[] = []
  const updated: string[] = []

  for (const [key, value] of entries) {
    const line = formatLine(key, value)
    const keyRegExp = new RegExp(`^${escapeRegExp(key)}=.*$`, 'm')

    if (keyRegExp.test(content)) {
      content = content.replace(keyRegExp, line)
      updated.push(key)
    } else {
      if (content.length > 0 && !content.endsWith('\n')) {
        content += '\n'
      }
      content += `${line}\n`
      added.push(key)
    }
  }

  fs.writeFileSync(envPath, content)
  return { created: false, added, updated }
}

/**
 * Checks whether the `.gitignore` file in the given directory ignores `.env`.
 *
 * Returns `'no-file'` if no `.gitignore` exists, `'ok'` if it ignores `.env`, and
 * `'missing-entry'` if it exists but does not ignore `.env`.
 */
export function checkGitignore(dir: string): GitignoreStatus {
  const gitignorePath = path.join(dir, '.gitignore')

  if (!fs.existsSync(gitignorePath)) {
    return 'no-file'
  }

  const content = fs.readFileSync(gitignorePath, 'utf8')
  const lines = content.split(/\r?\n/).map((line) => line.trim())

  if (lines.includes('.env') || lines.includes('/.env')) {
    return 'ok'
  }

  return 'missing-entry'
}

/**
 * Writes the connection string of the given connection to the `DATABASE_URL` entry of
 * the `.env` file in the given directory.
 */
export function writeLocalFiles(dir: string, connection: ConnectionResult): { env: EnvFileResult } {
  const envPath = path.join(dir, '.env')
  const env = upsertEnvFile(envPath, { DATABASE_URL: connection.connectionString })
  return { env }
}

/**
 * Returns `true` if the `.env` file in the given directory contains a `DATABASE_URL`
 * pointing to a Prisma Postgres host (`db.prisma.io` or `db-pool.prisma.io`).
 */
export function isAlreadyLinked(dir: string): boolean {
  const envPath = path.join(dir, '.env')

  if (!fs.existsSync(envPath)) {
    return false
  }

  const content = fs.readFileSync(envPath, 'utf8')
  const match = content.match(/^\s*DATABASE_URL\s*=\s*(.+)$/m)

  if (!match) {
    return false
  }

  const value = match[1]
  return value.includes('db.prisma.io') || value.includes('db-pool.prisma.io')
}

/**
 * Formats a human-readable summary of the `.env` file operation, including a warning
 * when the `.gitignore` does not ignore `.env`.
 */
export function formatEnvSummary(opts: { env: EnvFileResult; gitignoreStatus: GitignoreStatus }): string {
  const { env, gitignoreStatus } = opts

  let summary = env.created ? '  Created .env with connection strings' : '  Updated .env with connection strings'

  if (gitignoreStatus === 'missing-entry') {
    summary += '\n    warn Your .gitignore does not include .env — add it to avoid committing secrets'
  } else if (gitignoreStatus === 'no-file') {
    summary += '\n    warn No .gitignore found — create one and add .env to avoid committing secrets'
  }

  return summary
}
