import { bold, dim, red } from 'kleur/colors'

import { Link } from './link/Link'

/**
 * A subcommand that can be dispatched to by {@link PostgresCommand}.
 */
export type PostgresSubcommand = {
  parse: (args: string[], config: unknown, cwd: string) => Promise<string | Error>
}

/**
 * $ prisma postgres
 *
 * Top-level command for Prisma Postgres operations. Dispatches to registered
 * subcommands such as `link`.
 */
export class PostgresCommand {
  public static new(subcommands: Record<string, PostgresSubcommand> = {}): PostgresCommand {
    return new PostgresCommand({ link: Link.new(), ...subcommands })
  }

  private static help = format(`
Manage your Prisma Postgres databases.

${bold('Usage')}

  ${dim('$')} prisma postgres [command] [options]

${bold('Commands')}

  link   Link your local project to a Prisma Postgres database

${bold('Options')}

  -h, --help   Display this help message

${bold('Examples')}

  Link your local project to a Prisma Postgres database
  ${dim('$')} prisma postgres link
`)

  private constructor(private readonly subcommands: Record<string, PostgresSubcommand>) {}

  public async parse(argv: string[], config: unknown, cwd: string = process.cwd()): Promise<string | Error> {
    const args = arg(argv, {
      '--help': Boolean,
      '-h': '--help',
    })

    if (isError(args)) {
      return this.help(args.message)
    }

    if (args._.length === 0 || args['--help']) {
      return this.help()
    }

    const subcommandName = args._[0]
    const subcommand = this.subcommands[subcommandName]
    if (subcommand) {
      return subcommand.parse(args._.slice(1), config, cwd)
    }

    return unknownCommand(PostgresCommand.help, subcommandName)
  }

  public help(error?: string): string | HelpError {
    if (error) {
      return new HelpError(`\n${bold(red('!'))} ${error}\n${PostgresCommand.help}`)
    }
    return PostgresCommand.help
  }
}
